window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-50abaa3f803ca01d"]={"versions": [{"id": "FIG-50abaa3f803ca01d", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, MCAL-Schicht (Microcontroller Abstraction Layer). Das Diagramm spezifiziert die Laufzeit-Umschaltung der Funktionalität/des Multiplexings eines einzelnen Microcontroller-Pins über das BSW-Modul <code>Port</code> (<code>AUTOSAR_SWS_PortDriver</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Generic Elements::User</code> (Lifeline):</strong>\n<ul class=\"fig-list\"><li>Aufrufende BSW- oder SWC-Entität (z. B. I/O Hardware Abstraction, Complex Device Driver (CDD) oder RTE/Applikation).\n</li></ul>\n</li><li><strong><code>Port::Port</code> (Lifeline):</strong>\n<ul class=\"fig-list\"><li>Instanz des AUTOSAR Port Drivers (MCAL-Modul <code>Port</code>).\n</li></ul>\n</li><li><strong>Schnittstelle / API:</strong>\n<ul class=\"fig-list\"><li><code>Port_SetPinMode(Port_PinType Pin, Port_PinModeType Mode)</code>: Synchrone Steuerungsfunktion zur dynamischen Zuweisung einer alternativen Pin-Funktionalität (z. B. GPIO, SPI-MOSI, CAN-TX, ADC-Input, PWM).\n</li></ul>\n</li><li><strong>Zustandsnotiz / Postcondition:</strong>\n<ul class=\"fig-list\"><li><em>„The port pin mode is set“</em>: Nach Rückkehr der API ist die Hardware-Registerkonfiguration für den angegebenen Pin abgeschlossen und aktiv.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Aufruf:</strong> <code>Generic Elements::User</code> ruft synchron <code>Port_SetPinMode(Pin, Mode)</code> am Port-Treiber auf.\n</li><li><strong>Treiber-Ausführung:</strong>\n<ul class=\"fig-list\"><li>Der Port-Treiber blockiert temporär den aufrufenden Kontext während der direkten Hardware-Register-Manipulation (Pin Multiplexing / Alternate Function Register des MCUs).\n</li></ul>\n</li><li><strong>Abschluss &amp; Rückkehr:</strong>\n<ul class=\"fig-list\"><li>Nach erfolgreicher Modus-Konfiguration am Peripherie-/Port-Controller kehrt die Funktion ohne Rückgabewert (<code>void</code>) synchron an den Aufrufer zurück (<code>Port_SetPinMode</code>).\n</li></ul>\n</li><li><strong>Fehlerpfade / Validierung (SWS-Regelwerk):</strong>\n<ul class=\"fig-list\"><li>Bei aktivierter Entwicklungsfehler-Erkennung (<code>PORT_DEV_ERROR_DETECT == STD_ON</code>) erfolgt vor der Register-Manipulation eine Prüfung:\n<ul class=\"fig-list\"><li>Treiber initialisiert (<code>PORT_E_UNINIT</code>).\n</li><li><code>Pin</code> gültig (<code>PORT_E_PARAM_PIN</code>).\n</li><li><code>Mode</code> für diesen Pin gültig (<code>PORT_E_PARAM_INVALID_MODE</code>).\n</li><li>Pin zur Laufzeit modifizierbar (<code>PORT_E_MODE_UNCHANGEABLE</code>).\n</li></ul>\n</li><li>Bei Fehlern wird Det (<code>Det_ReportError</code>) aufgerufen und der Registerzugriff verworfen.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Präprozessor- &amp; Konfigurations-Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Die API steht nur zur Verfügung, wenn der Pre-Compile-Parameter <code>PortSetPinModeApi</code> auf <code>TRUE</code> konfiguriert ist.\n</li><li>Für den adressierten Pin muss im BSW-Datenmodell (<code>PortConfigSet/PortContainer/PortPin</code>) der Parameter <code>PortPinModeChangeable == TRUE</code> gesetzt sein; andernfalls ist der Modus statisch und die API-Nutzung unzulässig.\n</li></ul>\n</li><li><strong>Reentranz &amp; Nebenläufigkeit:</strong>\n<ul class=\"fig-list\"><li><code>Port_SetPinMode</code> ist normativ <strong>reentrant für unterschiedliche Pins</strong>, jedoch <strong>nicht-reentrant für denselben Pin</strong>.\n</li><li>Bei Shared-Register-Architekturen (mehrere Pins teilen sich ein Control-/Mux-Register) muss die Treiber-Implementierung atomare Read-Modify-Write-Operationen sicherstellen (z. B. Interrupt-Sperre oder bit-banding/Hardware-Atomic-Mask).\n</li></ul>\n</li><li><strong>Laufzeiteffekte:</strong>\n<ul class=\"fig-list\"><li>Der Moduswechsel kann Glitches, Pegelwechsel oder ungültige Signalzustände an angeschlossenen Transceivern/Aktoren auslösen. Abhängige BSW-Module (z. B. <code>Dio</code>, <code>Spi</code>, <code>Can</code>) müssen während des Umschaltvorgangs in einem definierten/deaktivierten Zustand sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f31c0e155b7720d0", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, MCAL-Schicht (Microcontroller Abstraction Layer). Das Diagramm spezifiziert die Laufzeit-Umschaltung der Funktionalität/des Multiplexings eines einzelnen Microcontroller-Pins über das BSW-Modul <code>Port</code> (<code>AUTOSAR_SWS_PortDriver</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>User</code> (Lifeline):</strong>\n<ul class=\"fig-list\"><li>Aufrufende BSW- oder SWC-Entität (z. B. I/O Hardware Abstraction, Complex Device Driver (CDD) oder RTE/Applikation).\n</li></ul>\n</li><li><strong><code>«module» Port</code> (Lifeline):</strong>\n<ul class=\"fig-list\"><li>Instanz des AUTOSAR Port Drivers (MCAL-Modul <code>Port</code>).\n</li></ul>\n</li><li><strong>Schnittstelle / API:</strong>\n<ul class=\"fig-list\"><li><code>Port_SetPinMode(Port_PinType, Port_PinModeType)</code>: Synchrone Steuerungsfunktion zur dynamischen Zuweisung einer alternativen Pin-Funktionalität (z. B. GPIO, SPI-MOSI, CAN-TX, ADC-Input, PWM); Rückkehr synchron über <code>Port_SetPinMode()</code>.\n</li></ul>\n</li><li><strong>Zustandsnotiz / Postcondition:</strong>\n<ul class=\"fig-list\"><li><em>„The port pin mode is set“</em>: Nach Rückkehr der API ist die Hardware-Registerkonfiguration für den angegebenen Pin abgeschlossen und aktiv (an der Rückkehrnachricht annotiert).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Aufruf:</strong> <code>User</code> ruft synchron <code>Port_SetPinMode(Port_PinType, Port_PinModeType)</code> am Port-Treiber (<code>Port</code>) auf.\n</li><li><strong>Treiber-Ausführung:</strong>\n<ul class=\"fig-list\"><li>Der Port-Treiber blockiert temporär den aufrufenden Kontext während der direkten Hardware-Register-Manipulation (Pin Multiplexing / Alternate Function Register des MCUs).\n</li></ul>\n</li><li><strong>Abschluss &amp; Rückkehr:</strong>\n<ul class=\"fig-list\"><li>Nach erfolgreicher Modus-Konfiguration am Peripherie-/Port-Controller kehrt die Funktion ohne Rückgabewert (<code>void</code>) synchron an den Aufrufer zurück (<code>Port_SetPinMode()</code>); Zustand: <em>„The port pin mode is set“</em>.\n</li></ul>\n</li><li><strong>Fehlerpfade / Validierung (SWS-Regelwerk):</strong>\n<ul class=\"fig-list\"><li>Bei aktivierter Entwicklungsfehler-Erkennung (<code>PORT_DEV_ERROR_DETECT == STD_ON</code>) erfolgt vor der Register-Manipulation eine Prüfung:\n<ul class=\"fig-list\"><li>Treiber initialisiert (<code>PORT_E_UNINIT</code>).\n</li><li><code>Pin</code> gültig (<code>PORT_E_PARAM_PIN</code>).\n</li><li><code>Mode</code> für diesen Pin gültig (<code>PORT_E_PARAM_INVALID_MODE</code>).\n</li><li>Pin zur Laufzeit modifizierbar (<code>PORT_E_MODE_UNCHANGEABLE</code>).\n</li></ul>\n</li><li>Bei Fehlern wird Det (<code>Det_ReportError</code>) aufgerufen und der Registerzugriff verworfen.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Präprozessor- &amp; Konfigurations-Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Die API steht nur zur Verfügung, wenn der Pre-Compile-Parameter <code>PortSetPinModeApi</code> auf <code>TRUE</code> konfiguriert ist.\n</li><li>Für den adressierten Pin muss im BSW-Datenmodell (<code>PortConfigSet/PortContainer/PortPin</code>) der Parameter <code>PortPinModeChangeable == TRUE</code> gesetzt sein; andernfalls ist der Modus statisch und die API-Nutzung unzulässig.\n</li></ul>\n</li><li><strong>Reentranz &amp; Nebenläufigkeit:</strong>\n<ul class=\"fig-list\"><li><code>Port_SetPinMode</code> ist normativ <strong>reentrant für unterschiedliche Pins</strong>, jedoch <strong>nicht-reentrant für denselben Pin</strong>.\n</li><li>Bei Shared-Register-Architekturen (mehrere Pins teilen sich ein Control-/Mux-Register) muss die Treiber-Implementierung atomare Read-Modify-Write-Operationen sicherstellen (z. B. Interrupt-Sperre oder bit-banding/Hardware-Atomic-Mask).\n</li></ul>\n</li><li><strong>Laufzeiteffekte:</strong>\n<ul class=\"fig-list\"><li>Der Moduswechsel kann Glitches, Pegelwechsel oder ungültige Signalzustände an angeschlossenen Transceivern/Aktoren auslösen. Abhängige BSW-Module (z. B. <code>Dio</code>, <code>Spi</code>, <code>Can</code>) müssen während des Umschaltvorgangs in einem definierten/deaktivierten Zustand sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-b973169fe7a14d54", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, MCAL-Schicht (Microcontroller Abstraction Layer). Das Diagramm spezifiziert die Laufzeit-Umschaltung der Funktionalität/des Multiplexings eines einzelnen Microcontroller-Pins über das BSW-Modul <code>Port</code> (<code>AUTOSAR_SWS_PortDriver</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>User</code> (Lifeline):</strong>\n<ul class=\"fig-list\"><li>Aufrufende BSW- oder SWC-Entität (z. B. I/O Hardware Abstraction, Complex Device Driver (CDD) oder RTE/Applikation).\n</li></ul>\n</li><li><strong><code>«module» Port</code> (Lifeline):</strong>\n<ul class=\"fig-list\"><li>Instanz des AUTOSAR Port Drivers (MCAL-Modul <code>Port</code>).\n</li></ul>\n</li><li><strong>Schnittstelle / API:</strong>\n<ul class=\"fig-list\"><li><code>Port_SetPinMode(Port_PinType, Port_PinModeType)</code>: Synchrone Steuerungsfunktion zur dynamischen Zuweisung einer alternativen Pin-Funktionalität (z. B. GPIO, SPI-MOSI, CAN-TX, ADC-Input, PWM); Rückkehr synchron über <code>Port_SetPinMode()</code>.\n</li></ul>\n</li><li><strong>Zustandsnotiz / Postcondition:</strong>\n<ul class=\"fig-list\"><li><em>„The port pin mode is set“</em>: Nach Rückkehr der API ist die Hardware-Registerkonfiguration für den angegebenen Pin abgeschlossen und aktiv (an der Rückkehrnachricht annotiert).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Aufruf:</strong> <code>User</code> ruft synchron <code>Port_SetPinMode(Port_PinType, Port_PinModeType)</code> am Port-Treiber (<code>Port</code>) auf.\n</li><li><strong>Treiber-Ausführung:</strong>\n<ul class=\"fig-list\"><li>Der Port-Treiber blockiert temporär den aufrufenden Kontext während der direkten Hardware-Register-Manipulation (Pin Multiplexing / Alternate Function Register des MCUs).\n</li></ul>\n</li><li><strong>Abschluss &amp; Rückkehr:</strong>\n<ul class=\"fig-list\"><li>Nach erfolgreicher Modus-Konfiguration am Peripherie-/Port-Controller kehrt die Funktion ohne Rückgabewert (<code>void</code>) synchron an den Aufrufer zurück (<code>Port_SetPinMode()</code>); Zustand: <em>„The port pin mode is set“</em>.\n</li></ul>\n</li><li><strong>Fehlerpfade / Validierung (SWS-Regelwerk):</strong>\n<ul class=\"fig-list\"><li>Bei aktivierter Entwicklungsfehler-Erkennung (<code>PORT_DEV_ERROR_DETECT == STD_ON</code>) erfolgt vor der Register-Manipulation eine Prüfung:\n<ul class=\"fig-list\"><li>Treiber initialisiert (<code>PORT_E_UNINIT</code>).\n</li><li><code>Pin</code> gültig (<code>PORT_E_PARAM_PIN</code>).\n</li><li><code>Mode</code> für diesen Pin gültig (<code>PORT_E_PARAM_INVALID_MODE</code>).\n</li><li>Pin zur Laufzeit modifizierbar (<code>PORT_E_MODE_UNCHANGEABLE</code>).\n</li></ul>\n</li><li>Bei Fehlern wird Det (<code>Det_ReportError</code>) aufgerufen und der Registerzugriff verworfen.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Präprozessor- &amp; Konfigurations-Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Die API steht nur zur Verfügung, wenn der Pre-Compile-Parameter <code>PortSetPinModeApi</code> auf <code>TRUE</code> konfiguriert ist.\n</li><li>Für den adressierten Pin muss im BSW-Datenmodell (<code>PortConfigSet/PortContainer/PortPin</code>) der Parameter <code>PortPinModeChangeable == TRUE</code> gesetzt sein; andernfalls ist der Modus statisch und die API-Nutzung unzulässig.\n</li></ul>\n</li><li><strong>Reentranz &amp; Nebenläufigkeit:</strong>\n<ul class=\"fig-list\"><li><code>Port_SetPinMode</code> ist normativ <strong>reentrant für unterschiedliche Pins</strong>, jedoch <strong>nicht-reentrant für denselben Pin</strong>.\n</li><li>Bei Shared-Register-Architekturen (mehrere Pins teilen sich ein Control-/Mux-Register) muss die Treiber-Implementierung atomare Read-Modify-Write-Operationen sicherstellen (z. B. Interrupt-Sperre oder bit-banding/Hardware-Atomic-Mask).\n</li></ul>\n</li><li><strong>Laufzeiteffekte:</strong>\n<ul class=\"fig-list\"><li>Der Moduswechsel kann Glitches, Pegelwechsel oder ungültige Signalzustände an angeschlossenen Transceivern/Aktoren auslösen. Abhängige BSW-Module (z. B. <code>Dio</code>, <code>Spi</code>, <code>Can</code>) müssen während des Umschaltvorgangs in einem definierten/deaktivierten Zustand sein.\n</li></ul>\n</li></ul>"}, {"id": "FIG-586e555e7b5f60db", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, MCAL-Schicht (Microcontroller Abstraction Layer). Das Diagramm spezifiziert die Laufzeit-Umschaltung der Funktionalität/des Multiplexings eines einzelnen Microcontroller-Pins über das BSW-Modul <code>Port</code> (<code>AUTOSAR_SWS_PortDriver</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>User</code> (Lifeline):</strong>\n<ul class=\"fig-list\"><li>Aufrufende BSW- oder SWC-Entität (z. B. I/O Hardware Abstraction, Complex Device Driver (CDD) oder RTE/Applikation).\n</li></ul>\n</li><li><strong><code>«module» Port</code> (Lifeline):</strong>\n<ul class=\"fig-list\"><li>Instanz des AUTOSAR Port Drivers (MCAL-Modul <code>Port</code>).\n</li></ul>\n</li><li><strong>Schnittstelle / API:</strong>\n<ul class=\"fig-list\"><li><code>Port_SetPinMode(Port_PinType, Port_PinModeType)</code>: Synchrone Steuerungsfunktion zur dynamischen Zuweisung einer alternativen Pin-Funktionalität (z. B. GPIO, SPI-MOSI, CAN-TX, ADC-Input, PWM); Rückkehr synchron über <code>Port_SetPinMode()</code>.\n</li></ul>\n</li><li><strong>Zustandsnotiz / Postcondition:</strong>\n<ul class=\"fig-list\"><li><em>„The port pin mode is set“</em>: Nach Rückkehr der API ist die Hardware-Registerkonfiguration für den angegebenen Pin abgeschlossen und aktiv (an der Rückkehrnachricht annotiert).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Aufruf:</strong> <code>User</code> ruft synchron <code>Port_SetPinMode(Port_PinType, Port_PinModeType)</code> am Port-Treiber (<code>Port</code>) auf.\n</li><li><strong>Treiber-Ausführung:</strong>\n<ul class=\"fig-list\"><li>Der Port-Treiber blockiert temporär den aufrufenden Kontext während der direkten Hardware-Register-Manipulation (Pin Multiplexing / Alternate Function Register des MCUs).\n</li></ul>\n</li><li><strong>Abschluss &amp; Rückkehr:</strong>\n<ul class=\"fig-list\"><li>Nach erfolgreicher Modus-Konfiguration am Peripherie-/Port-Controller kehrt die Funktion ohne Rückgabewert (<code>void</code>) synchron an den Aufrufer zurück (<code>Port_SetPinMode()</code>); Zustand: <em>„The port pin mode is set“</em>.\n</li></ul>\n</li><li><strong>Fehlerpfade / Validierung (SWS-Regelwerk):</strong>\n<ul class=\"fig-list\"><li>Bei aktivierter Entwicklungsfehler-Erkennung (<code>PORT_DEV_ERROR_DETECT == STD_ON</code>) erfolgt vor der Register-Manipulation eine Prüfung:\n<ul class=\"fig-list\"><li>Treiber initialisiert (<code>PORT_E_UNINIT</code>).\n</li><li><code>Pin</code> gültig (<code>PORT_E_PARAM_PIN</code>).\n</li><li><code>Mode</code> für diesen Pin gültig (<code>PORT_E_PARAM_INVALID_MODE</code>).\n</li><li>Pin zur Laufzeit modifizierbar (<code>PORT_E_MODE_UNCHANGEABLE</code>).\n</li></ul>\n</li><li>Bei Fehlern wird Det (<code>Det_ReportError</code>) aufgerufen und der Registerzugriff verworfen.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Präprozessor- &amp; Konfigurations-Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Die API steht nur zur Verfügung, wenn der Pre-Compile-Parameter <code>PortSetPinModeApi</code> auf <code>TRUE</code> konfiguriert ist.\n</li><li>Für den adressierten Pin muss im BSW-Datenmodell (<code>PortConfigSet/PortContainer/PortPin</code>) der Parameter <code>PortPinModeChangeable == TRUE</code> gesetzt sein; andernfalls ist der Modus statisch und die API-Nutzung unzulässig.\n</li></ul>\n</li><li><strong>Reentranz &amp; Nebenläufigkeit:</strong>\n<ul class=\"fig-list\"><li><code>Port_SetPinMode</code> ist normativ <strong>reentrant für unterschiedliche Pins</strong>, jedoch <strong>nicht-reentrant für denselben Pin</strong>.\n</li><li>Bei Shared-Register-Architekturen (mehrere Pins teilen sich ein Control-/Mux-Register) muss die Treiber-Implementierung atomare Read-Modify-Write-Operationen sicherstellen (z. B. Interrupt-Sperre oder bit-banding/Hardware-Atomic-Mask).\n</li></ul>\n</li><li><strong>Laufzeiteffekte:</strong>\n<ul class=\"fig-list\"><li>Der Moduswechsel kann Glitches, Pegelwechsel oder ungültige Signalzustände an angeschlossenen Transceivern/Aktoren auslösen. Abhängige BSW-Module (z. B. <code>Dio</code>, <code>Spi</code>, <code>Can</code>) müssen während des Umschaltvorgangs in einem definierten/deaktivierten Zustand sein.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-50abaa3f803ca01d", "to": "FIG-f31c0e155b7720d0", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Lifelines:</strong> <code>Generic Elements::User</code> wurde zu <code>User</code> vereinfacht; <code>Port::Port</code> wurde zu <code>Port</code> mit Stereotyp <code>«module»</code> geändert.\n</li><li><strong>Aufruf <code>Port_SetPinMode</code>:</strong> Parameternamen <code>(Pin, Mode)</code> durch Parametertypen <code>(Port_PinType, Port_PinModeType)</code> ersetzt.\n</li><li><strong>Rückkehr <code>Port_SetPinMode</code>:</strong> Methodenklammern ergänzt (<code>Port_SetPinMode()</code>).\n</li><li><strong>Zustandsnotiz:</strong> Die Notiz <em>„The port pin mode is set“</em> ist nun an die Rückkehrnachricht statt an die <code>Port</code>-Lifeline gekoppelt.\n</li><li><strong>Kommentarfeld:</strong> Das Textfeld unten links (<em>„Description: Set the mode of a port pin / Comments“</em>) wurde entfernt.\n</li><li><strong>Layout:</strong> Vollständiges Redesign im neueren UML-Stil.\n</li></ul>"}, {"from": "FIG-f31c0e155b7720d0", "to": "FIG-b973169fe7a14d54", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b973169fe7a14d54", "to": "FIG-586e555e7b5f60db", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
